  "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">A new page will open as your whiteboard. You can draw, add shapes, sticky notes and connectors freely across the entire canvas.</p>": "<p style=\"margin:0 0 18px;font-size:12px;color:var(--text-dim);line-height:1.5;\">Uma nova página será aberta como quadro branco. Desenhe livremente e adicione formas, notas adesivas e conectores por toda a tela.</p>",
  "<button id=\"board-confirm-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;\">Cancel</button>": "<button id=\"board-confirm-cancel\" style=\"padding:8px 18px;border-radius:8px;border:1px solid var(--border);background:var(--surface2);color:var(--text-dim);font-size:12px;cursor:pointer;transition:all .12s;\">Cancelar</button>",
  "<button id=\"board-confirm-ok\" style=\"padding:8px 18px;border-radius:8px;border:none;background:var(--gold);color:#111;font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;\">Open Board</button>": "<button id=\"board-confirm-ok\" style=\"padding:8px 18px;border-radius:8px;border:none;background:var(--gold);color:#111;font-size:12px;font-weight:600;cursor:pointer;transition:all .12s;\">Abrir quadro</button>",
