  "This request comes from the Bulk Builder (PLAN pass). Read the instruction and the design fields, then LIST the outputs you will produce, LABELS ONLY (no field content). Return ONLY a raw JSON object: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. When translate is true the labels are the LANGUAGE NAMES (written in the same language the user used). Otherwise the labels are a distinct short topic/seed per output. Honor any quantity named in the instruction; otherwise a sensible set (about 6 to 12). Hard cap 500.\n": "Esta solicitação vem do Bulk Builder (passe PLAN). Leia as instruções e os campos de design e, em seguida, LISTA os resultados que você produzirá, SOMENTE ETIQUETAS (sem conteúdo de campo). Retorne SOMENTE um objeto JSON bruto: {\"translate\": <true ONLY if the instruction asks to translate/localize into languages, else false>, \"labels\": [ ... ]}. Quando a tradução é verdadeira, os rótulos são os NOMES DE IDIOMA (escritos no mesmo idioma que o usuário usou). Caso contrário, os rótulos serão um tópico/semente curto e distinto por saída. Honre qualquer quantidade mencionada nas instruções; caso contrário, um conjunto sensato (cerca de 6 a 12). Tampa rígida 500.\n",
