  "Create your dika studio account": "Crie sua conta dika studio",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way.": "Uma conta dá acesso aos modelos e à biblioteca de recursos online, além das novidades. O editor funciona mesmo sem conta.",
  "This app could not reach dika studio just now, so the full sign-up flow is not available.": "Este aplicativo não conseguiu acessar dika studio agora; o cadastro completo não está disponível.",
  "You can carry on using the editor: everything except the online library works offline.": "Você pode continuar usando o editor: tudo, exceto a biblioteca online, funciona offline.",
  "It will ask again next time you open it.": "Ele perguntará novamente na próxima vez que você abri-lo.",
  "Registration wizard": "Assistente de registro",
  "<div style=\"font-size:28px;font-weight:700;color:var(--text);margin-bottom:4px\">dika studio</div>": "<div style=\"font-size:28px;font-weight:700;color:var(--text);margin-bottom:4px\">dika studio</div>",
  "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Multi-Product Design Platform</div>": "<div style=\"font-size:13px;color:var(--text-dim);margin-bottom:20px\">Plataforma de design para vários produtos</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Version 2.0</div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:4px\">Versão 2.0</div>",
  "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Built by <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>": "<div style=\"font-size:12px;color:var(--text-faint);margin-bottom:20px\">Criado por <a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none\">Mirex Agency</a></div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">&copy; 2026 Mirex Agency. Released under the Business Source License 1.1.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-bottom:22px\">© Agência Mirex 2026. Lançado sob Business Source License 1.1.</div>",
  "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">Reset clears only the wizard's own record. Your projects, settings and keys are untouched.</div>": "<div style=\"font-size:11px;color:var(--text-faint);margin-top:10px\">A redefinição limpa apenas o registro do assistente. Seus projetos, configurações e chaves permanecem intactos.</div>",
  "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Need help? Contact us:</p>": "<p style=\"color:var(--text-dim);font-size:13px;margin-bottom:16px\">Precisa de ajuda? Fale conosco:</p>",
  "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visit our website</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"https://mirexagency.com\" target=\"_blank\" rel=\"noopener\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Visite nosso site</a></div>",
  "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Email support@dika.studio</a></div>": "<div style=\"margin-bottom:12px\"><a href=\"mailto:support@dika.studio\" style=\"color:var(--gold);text-decoration:none;font-size:13px\">Envie um e-mail para support@dika.studio</a></div>",
  "settings: about": "configurações: sobre",
  "<div class=\"settings-field\" id=\"account-panel\" style=\"margin-bottom:18px\">": "<div class=\"settings-field\" id=\"account-panel\" style=\"margin-bottom:18px\">",
  "<div style=\"font-size:12px;color:var(--text-dim);line-height:1.7\">": "<div style=\"font-size:12px;color:var(--text-dim);line-height:1.7\">",
  "<div>Plan: ": "<div>Plano: ",
