  "Your work stays here. Documents, media and version history never leave this computer.": "Seu trabalho fica aqui. Documentos, mídia e histórico de versões nunca saem deste computador.",
  "Free to use. Source available under the Business Source License 1.1.": "Uso gratuito. Código-fonte disponível sob a Business Source License 1.1.",
  "Your projects are stored in this browser profile. That is the only copy.": "Seus projetos são armazenados neste perfil de navegador. Essa é a única cópia.",
  "Clearing site data deletes them. So does a different browser, or a fresh profile.": "Limpar os dados do site os exclui. O mesmo acontece com um navegador diferente ou um perfil novo.",
  "Export a project file for anything you want to keep. It carries the design and its media, and it opens on any machine.": "Exporte um arquivo de projeto para qualquer coisa que você queira manter. Ele carrega o design e sua mídia e abre em qualquer máquina.",
  "Export a project file now": "Exporte um arquivo de projeto agora",
  "Remind me to export": "Lembre-me de exportar",
  "Never": "Nunca",
  "Weekly": "Semanalmente",
  "Monthly": "Mensal",
  "That is everything. Your work stays on this machine.": "Isso é tudo. Seu trabalho permanece nesta máquina.",
  "You can reopen this from Settings > About.": "Você pode reabrir isso em Configurações > Sobre.",
  "Start using it": "Comece a usá-lo",
  "Your profile data is used in contact presets and bulk export.": "Seus dados de perfil são usados em predefinições de contato e na exportação em massa.",
  "JOB TITLE": "CARGO",
  "ADDRESS": "ENDEREÇO",
  "Social Media": "Mídias Sociais",
  "Save Profile": "Salvar perfil",
  "An account unlocks the online template and asset library, and release news. The editor itself works either way, online or offline.": "Uma conta dá acesso aos modelos e à biblioteca de recursos online, além das novidades. O editor funciona online e offline.",
  "Sign in to unlock:": "Faça login para desbloquear:",
  "The online template and asset library": "O modelo online e a biblioteca de ativos",
  "Release news and early access to new features": "Divulgue novidades e acesso antecipado a novos recursos",
  "The editor itself works either way, with or without an account, online or offline.": "O próprio editor funciona de qualquer maneira, com ou sem conta, online ou offline.",
  "Create an account": "Crie uma conta",
  "WHAT THIS APP SENDS": "O QUE ESTE APLICATIVO ENVIA",
  "Once a day: an install id, the app version, your platform and language, and your account id once you sign in.": "Uma vez por dia: um ID de instalação, a versão do aplicativo, sua plataforma e idioma, e o ID da sua conta depois de fazer login.",
  "Nothing about your designs. No document, no title, no file name, no image.": "Nenhuma informação sobre seus designs: nenhum documento, título, nome de arquivo ou imagem.",
  "WHERE THE SESSION IS KEPT": "ONDE A SESSÃO É MANTIDA",
  "You are running the browser build, where every local page shares one storage area, so another local file opened in this browser could read this session. It is therefore short-lived (about 24 hours) and can only read the template library. The desktop app keeps its own isolated storage.": "Você está executando a compilação do navegador, onde cada página local compartilha uma área de armazenamento, para que outro arquivo local aberto neste navegador possa ler esta sessão. Portanto, tem vida curta (cerca de 24 horas) e só pode ler a biblioteca de modelos. O aplicativo de desktop mantém seu próprio armazenamento isolado.",
  "Your own keys for the stock media providers. They fill the Images and Audio search tabs, and the GIFs and Stickers tabs in Items. Every provider below has a free tier.": "Suas chaves para provedores de mídia de banco. Elas alimentam as abas de busca de Imagens e Áudio e as abas de GIFs e Adesivos em Itens. Cada provedor abaixo oferece uma cota gratuita.",
  "These keys are stored in this browser only, and this build never sends them anywhere except to the provider itself. Anyone with access to this computer or its browser profile can read them, so use a restricted key with the lowest quota you need.": "Essas chaves são armazenadas apenas neste navegador e esta compilação nunca as envia para nenhum lugar, exceto para o próprio provedor. Qualquer pessoa com acesso a este computador ou ao seu perfil de navegador pode lê-los, portanto, use uma chave restrita com a cota mais baixa necessária.",
  "Save keys": "Salvar chaves",
  "1. Go to unsplash.com/oauth/applications and create an app": "1. Acesse unsplash.com/oauth/applications e crie um aplicativo",
  "2. Copy the Access Key, not the Secret Key": "2. Copie a chave de acesso, não a chave secreta",
  "Header: Authorization: Client-ID YOUR_KEY - 50 req/hr on demo, 5000 req/hr in production": "Cabeçalho: Autorização: Client-ID YOUR_KEY - 50 req/h em demonstração, 5.000 req/h em produção",
  "1. Go to pexels.com/api and request a key": "1. Acesse pexels.com/api e solicite uma chave",
  "2. It is issued instantly": "2. É emitido instantaneamente",
  "Header: Authorization: YOUR_KEY - 200 req/hr, 20K req/month": "Cabeçalho: Autorização: YOUR_KEY - 200 solicitações/hora, 20 mil solicitações/mês",
  "1. Go to pixabay.com/api/docs/ and sign up": "1. Acesse pixabay.com/api/docs/ e inscreva-se",
  "2. Copy the key shown on the docs page": "2. Copie a chave mostrada na página de documentos",
  "500K+ CC-licensed sound effects - header: Authorization: Token YOUR_KEY": "Mais de 500 mil efeitos sonoros licenciados por CC - cabeçalho: Autorização: Token YOUR_KEY",
  "1. Go to freesound.org/apiv2/apply and create an API app": "1. Acesse freesound.org/apiv2/apply e crie um aplicativo API",
  "2. Copy the API Token": "2. Copie o token da API",
  "1. Go to devportal.jamendo.com and register an app": "1. Acesse devportal.jamendo.com e registre um aplicativo",
  "2. Copy the Client ID": "2. Copie o ID do cliente",
  "1. Go to developers.giphy.com and create an app": "1. Acesse developers.giphy.com e crie um aplicativo",
  "2. Copy the API Key": "2. Copie a chave API",
