  "Skip Startup Wizard": "Ignorar assistente de inicialização",
  "In multi-page projects, to keep the app fast, pages you haven't opened for a long time are put to sleep in the background. Their content is safely stored and instantly returns when you click its tab. The page you're working on, a few nearby pages, and video / infinite canvas / slide / board pages always stay open.": "Em projetos com várias páginas, para manter o aplicativo rápido, as páginas que você não abre há algum tempo entram em suspensão em segundo plano. O conteúdo é armazenado com segurança e retorna instantaneamente quando você clica na aba. A página em que você trabalha, algumas páginas próximas e páginas de vídeo, tela infinita, apresentação e quadro permanecem sempre abertas.",
  "Automatic sleep": "Sono automático",
