  "Export a project file first if you want to keep anything. This does not uninstall the program itself: use Windows Settings for that.": "Exporte primeiro um arquivo de projeto se quiser manter alguma coisa. Isso não desinstala o programa em si: use as Configurações do Windows para isso.",
